19	    public T transform(T root, TraverserVisitor<T> traverserVisitor) {
20	        assertNotNull(root);
21	
22	        NodeMultiZipper<T> astMultiZipper = new NodeMultiZipper<>(root, Collections.emptyList(), nodeAdapter);
23	
24	        TraverserVisitor<T> nodeTraverserVisitor = new TraverserVisitor<T>() {
25	
26	            @Override
27	            public TraversalControl enter(TraverserContext<T> context) {
28	                NodeZipper<T> nodeZipper = new NodeZipper<>(context.thisNode(), context.getBreadcrumbs(), nodeAdapter);
29	                context.setVar(NodeZipper.class, nodeZipper);
30	                context.setVar(NodeAdapter.class, nodeAdapter);
31	                return traverserVisitor.enter(context);
32	            }
33	
34	            @Override
35	            public TraversalControl leave(TraverserContext<T> context) {
36	                return traverserVisitor.leave(context);
37	            }
38	        };
