16	/**
17	 * Lets you traverse a {@link Node} tree.
18	 */
19	@PublicApi
20	public class NodeTraverser {
21	
22	
23	    /**
24	     * Used to indicate via {@link TraverserContext#getVar(Class)} if the visit happens inside the ENTER or LEAVE phase.
25	     */
26	    public enum LeaveOrEnter {
27	        LEAVE,
28	        ENTER
29	    }
30	
31	    private final Map<Class<?>, Object> rootVars;
32	    private final Function<? super Node, ? extends List<Node>> getChildren;
33	
34	    public NodeTraverser(Map<Class<?>, Object> rootVars, Function<? super Node, ? extends List<Node>> getChildren) {
35	        this.rootVars = rootVars;
36	        this.getChildren = getChildren;
37	    }
38	
39	    public NodeTraverser() {
40	        this(Collections.emptyMap(), Node::getChildren);
41	    }
42	
43	
44	    /**
45	     * depthFirst traversal with a enter/leave phase.
46	     *
47	     * @param nodeVisitor the visitor of the nodes
48	     * @param root        the root node
49	     *
50	     * @return the accumulation result of this traversal
51	     */
52	    public Object depthFirst(NodeVisitor nodeVisitor, Node root) {
53	        return depthFirst(nodeVisitor, Collections.singleton(root));
54	    }
55	
56	    /**
57	     * depthFirst traversal with a enter/leave phase.
58	     *
59	     * @param nodeVisitor the visitor of the nodes
60	     * @param roots       the root nodes
61	     *
62	     * @return the accumulation result of this traversal
63	     */
64	    public Object depthFirst(NodeVisitor nodeVisitor, Collection<? extends Node> roots) {
65	        TraverserVisitor<Node> nodeTraverserVisitor = new TraverserVisitor<Node>() {
66	
67	            @Override
68	            public TraversalControl enter(TraverserContext<Node> context) {
69	                context.setVar(LeaveOrEnter.class, LeaveOrEnter.ENTER);
70	                return context.thisNode().accept(context, nodeVisitor);
71	            }
72	
73	            @Override
74	            public TraversalControl leave(TraverserContext<Node> context) {
75	                context.setVar(LeaveOrEnter.class, LeaveOrEnter.LEAVE);
76	                return context.thisNode().accept(context, nodeVisitor);
77	            }
78	
79	        };
80	        return doTraverse(roots, nodeTraverserVisitor);
81	    }
82	
